    address(this),    // ✅ Include contract address (prevents cross-contract replay)
    block.chainid,    // ✅ Include chain ID (prevents cross-chain replay)
    poolId,           // ✅ Include pool ID in signature hash
    amount,
    nonce,
    msg.sender
));
